        using Voxels part=new(distance); using Voxels inner=new(distance);
        part.Offset(0.54000f); inner.Offset(-0.54000f); part.BoolSubtract(inner);
        part.Trim(new BBox3(new Vector3(-2.88000f,-5.08000f,-2.68000f),new Vector3(4.08000f,1.88000f,4.28000f)));
        part.Offset(.05f); part.Offset(-.05f);
